// 자동 생성: tools/forest_art/build.py (assets/forest_bg.png · forest_front.png). 해안~땅굴 배경 원화. 좌표는 원본 px × scale. imgParts 를 이어 붙이면 그림 data URI
window.FOREST_ART = {"scale": 0.85, "srcW": 8002, "srcH": 3975, "bg": {"w": 6802, "h": 3379, "ox": 0.0, "oy": 0.0, "imgParts": ["data:image/webp;base64,", "", "", "", "", "", "", ""]}, "front": {"w": 1180, "h": 632, "ox": 357.0, "oy": 1360.85, "imgParts": ["data:image/webp;base64,", ""]}, "stuck": [{"w": 501, "h": 260, "imgParts": ["data:image/webp;base64,", ""]}, {"w": 441, "h": 260, "imgParts": ["data:image/webp;base64,", ""]}]};
for (const L of [window.FOREST_ART.bg, window.FOREST_ART.front, ...(window.FOREST_ART.stuck || [])]) { L.img = L.imgParts.join(""); delete L.imgParts; }
